#!/usr/bin/env python3
"""Real native traffic using fixtures generated by SingBoxSidecar's JVM tests.

Only loopback is contacted by the proxy. The optional binary download is hash pinned.
Checks authenticated SOCKS, TLS trust/name rejection and payloads in BOTH directions.
"""
import argparse
import contextlib
import hashlib
import http.server
import io
import json
import os
from pathlib import Path
import secrets
import socket
import subprocess
import tarfile
import tempfile
import threading
import time
import urllib.request

SHA = "699a1b510aa4396b2176d32d1181920399ebf1e267835da6f3b598d0f7c24968"
URL = "https://github.com/SagerNet/sing-box/releases/download/v1.14.4/sing-box-1.14.4-linux-amd64.tar.gz"


def free_port():
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


def read_exact(s, n):
    data = bytearray()
    while len(data) < n:
        part = s.recv(n - len(data))
        if not part:
            raise OSError("closed stream")
        data.extend(part)
    return bytes(data)


def request(port, target, user, password, payload):
    with socket.create_connection(("127.0.0.1", port), timeout=4) as s:
        s.settimeout(4)
        s.sendall(b"\x05\x01\x02")
        assert read_exact(s, 2) == b"\x05\x02", "SOCKS must require authentication"
        u, p = user.encode(), password.encode()
        s.sendall(b"\x01" + bytes([len(u)]) + u + bytes([len(p)]) + p)
        assert read_exact(s, 2) == b"\x01\x00", "SOCKS login rejected"
        s.sendall(b"\x05\x01\x00\x01\x7f\x00\x00\x01" + target.to_bytes(2, "big"))
        reply = read_exact(s, 4)
        assert reply[1] == 0, "SOCKS egress rejected"
        length = {1: 4, 4: 16}.get(reply[3])
        if length is None:
            length = read_exact(s, 1)[0]
        read_exact(s, length + 2)
        headers = f"POST /probe HTTP/1.1\r\nHost: localhost\r\nContent-Length: {len(payload)}\r\nConnection: close\r\n\r\n"
        s.sendall(headers.encode() + payload)
        response = bytearray()
        while True:
            part = s.recv(65536)
            if not part:
                break
            response.extend(part)
            assert len(response) <= 256 * 1024
        expected = hashlib.sha256(payload).hexdigest().encode() + b":" + payload
        assert bytes(response).split(b"\r\n\r\n", 1)[1] == expected, "upload or download payload mismatch"


@contextlib.contextmanager
def running(binary, config, path, port, env):
    path.write_text(json.dumps(config))
    subprocess.run([str(binary), "check", "-c", str(path)], env=env, check=True, capture_output=True)
    with open(path.with_suffix(".log"), "wb") as log:
        p = subprocess.Popen([str(binary), "run", "-c", str(path)], stdout=log, stderr=log, env=env)
        try:
            until = time.monotonic() + 10
            while True:
                assert p.poll() is None, "native engine exited: " + path.with_suffix(".log").read_text()[-2000:]
                try:
                    with socket.create_connection(("127.0.0.1", port), timeout=.1):
                        break
                except OSError:
                    assert time.monotonic() < until, "native engine startup timeout"
                    time.sleep(.05)
            yield
        finally:
            p.terminate()
            try:
                p.wait(timeout=5)
            except subprocess.TimeoutExpired:
                p.kill()
                p.wait(timeout=5)


def main():
    args = argparse.ArgumentParser()
    args.add_argument("--fixtures", required=True, type=Path)
    args.add_argument("--binary", type=Path)
    args = args.parse_args()
    fixtures = sorted(args.fixtures.glob("*.json"))
    assert len(fixtures) == 4, "expected four source-generated fixtures"
    with tempfile.TemporaryDirectory(prefix="singbox-test-") as directory:
        root = Path(directory)
        binary = args.binary
        if binary is None:
            with urllib.request.urlopen(URL, timeout=120) as r:
                data = r.read(100 * 1024 * 1024)
            assert hashlib.sha256(data).hexdigest() == SHA, "untrusted native executable archive"
            with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as archive:
                member = archive.extractfile("sing-box-1.14.4-linux-amd64/sing-box")
                assert member is not None
                binary = root / "sing-box"
                binary.write_bytes(member.read())
                binary.chmod(0o700)
        binary = binary.resolve()
        cert, key = root / "cert.pem", root / "key.pem"
        subprocess.run(["openssl", "req", "-x509", "-newkey", "rsa:2048", "-nodes", "-days", "1",
            "-subj", "/CN=example.com", "-addext", "subjectAltName=DNS:example.com", "-keyout", str(key), "-out", str(cert)],
            check=True, capture_output=True)

        class Echo(http.server.BaseHTTPRequestHandler):
            def do_POST(self):
                size = int(self.headers.get("Content-Length", "0"))
                assert 0 < size <= 65536
                data = self.rfile.read(size)
                response = hashlib.sha256(data).hexdigest().encode() + b":" + data
                self.send_response(200)
                self.send_header("Content-Length", str(len(response)))
                self.end_headers()
                self.wfile.write(response)

            def log_message(self, *args):
                pass

        server_http = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Echo)
        threading.Thread(target=server_http.serve_forever, daemon=True).start()
        try:
            for source in fixtures:
                client = json.loads(source.read_text())
                out = client["outbounds"][0]
                protocol = out["type"]
                server_port, socks_port = free_port(), free_port()
                out.update(server="127.0.0.1", server_port=server_port)
                inbound = client["inbounds"][0]
                inbound["listen_port"] = socks_port
                auth = inbound["users"][0]
                remote = dict(type=protocol, listen="127.0.0.1", listen_port=server_port)
                if protocol in ("vless", "vmess"):
                    remote["users"] = [dict(uuid=out["uuid"])]
                elif protocol == "trojan":
                    remote["users"] = [dict(password=out["password"])]
                else:
                    remote.update(method=out["method"], password=out["password"])
                if "tls" in out:
                    remote["tls"] = dict(enabled=True, certificate_path=str(cert), key_path=str(key))
                server = dict(log=dict(level="error"), inbounds=[remote], outbounds=[dict(type="direct", tag="direct")])
                env = dict(os.environ, SSL_CERT_FILE=str(cert))
                with running(binary, server, root / "server.json", server_port, env):
                    with running(binary, client, root / "client.json", socks_port, env):
                        request(socks_port, server_http.server_port, auth["username"], auth["password"], secrets.token_bytes(65536))
                        try:
                            request(socks_port, server_http.server_port, auth["username"], "wrong", b"must-not-pass")
                        except (AssertionError, OSError):
                            pass
                        else:
                            raise AssertionError("unauthenticated traffic escaped")
                    if "tls" in out:
                        for bad_name, trusted in ((True, True), (False, False)):
                            out["tls"]["server_name"] = "wrong.invalid" if bad_name else "example.com"
                            failure_env = env if trusted else dict(os.environ, SSL_CERT_FILE=str(root / "missing.pem"))
                            with running(binary, client, root / "client.json", socks_port, failure_env):
                                try:
                                    request(socks_port, server_http.server_port, auth["username"], auth["password"], b"must-not-pass")
                                except (AssertionError, OSError, IndexError):
                                    pass
                                else:
                                    raise AssertionError("TLS validation bypassed")
                print(f"PASS {protocol}: authenticated SOCKS, 64 KiB upload+download, TLS name/trust rejection where applicable")
        finally:
            server_http.shutdown()
            server_http.server_close()


if __name__ == "__main__":
    main()
